import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Стиль","description":"","frontmatter":{},"headers":[],"relativePath":"guide/style/index.md","filePath":"guide/style/index.md","lastUpdated":0}`),a={name:`guide/style/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="стиль" tabindex="-1">Стиль <a class="header-anchor" href="#стиль" aria-label="Permalink to “Стиль”">​</a></h1><p>Вкладка <strong>«Стиль»</strong> в попапе настроек отвечает за внешний вид данных и интерфейса. Часть оформления расширение подхватывает у редактора автоматически, чтобы панели не выбивались из нативного интерфейса.</p><h2 id="stroke-color" tabindex="-1">Обводка контура загруженного объекта <a class="header-anchor" href="#stroke-color" aria-label="Permalink to “Обводка контура загруженного объекта”">​</a></h2><p><strong>Где:</strong> Настройки → Стиль → «Обводка контура загруженного объекта».</p><p>Задаёт цвет обводки у объектов, которые вы загрузили в блокнот. Это помогает сразу отличить свои данные от нативных объектов карты.</p><ul><li>Формат ввода — <code>RGB</code> или <code>RRGGBB</code>, с <code>#</code> или без: <code>f0f</code>, <code>#ff00ff</code>, <code>FF00FF</code>.</li><li>Пустое поле возвращает цвет по умолчанию — <code>#ff00ff</code> (пурпурный).</li><li>Некорректное значение не применяется: поле подсвечивается, появляется сообщение «Введите цвет в формате RGB или RRGGBB».</li><li>После сохранения цвет применяется сразу, без перезагрузки.</li></ul><p>Сценарии:</p><ul><li><strong>Свои данные поверх чужих.</strong> Поставьте яркий цвет обводки, чтобы загруженные контуры не терялись среди нативных.</li><li><strong>Несколько наборов.</strong> Меняйте цвет перед каждой загрузкой — так разные партии данных визуально различаются.</li><li><strong>Скриншот для отчёта.</strong> Нейтральный цвет обводки, чтобы объект выглядел аккуратно на снимке экрана.</li></ul><div class="warning custom-block"><p class="custom-block-title">Если цвет не применился</p><p>Сообщение «Не удалось применить цвет. Обновите страницу карты и попробуйте снова» означает, что страница редактора была открыта до установки или обновления расширения. Обновите вкладку с картой — после этого настройка применится.</p></div><h2 id="native-theme" tabindex="-1">Тема редактора <a class="header-anchor" href="#native-theme" aria-label="Permalink to “Тема редактора”">​</a></h2><p>Отдельного переключателя тёмной и светлой темы нет: расширение <strong>всегда следует теме редактора</strong>. Переключили тему в Народной карте — панели, попап настроек, заметки и фильтры перекрасились вместе с ней.</p><p>Почему так: ручной выбор темы давал панелям оформление, отличное от редактора, и требовал синхронизации между всеми страницами расширения. Автоматическое следование убирает рассинхронизацию.</p><p>Сценарий: работаете ночью в тёмной теме — ничего дополнительно включать не нужно, попап и панели уже тёмные.</p><h2 id="native-locale" tabindex="-1">Язык редактора <a class="header-anchor" href="#native-locale" aria-label="Permalink to “Язык редактора”">​</a></h2><p>Расширение говорит на языке редактора: русский или английский. Язык берётся из атрибута <code>lang</code> страницы Народной карты и меняется вместе с ним, без перезагрузки расширения.</p><p>Если язык редактора не русский, интерфейс переключается на английский — редактор НЯК переводится на два языка. Ручного выбора языка в настройках нет по той же причине, что и у темы: один источник правды.</p><p>Сценарий: коллега работает в английской версии редактора — панели расширения у него тоже на английском, инструкция в справке при этом одна.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};